export function DownloadAction({
  fileName = "{{fileName}}",
  fileSize = "{{fileSize}}",
  state = "{{state}}",
  progress = {{progress}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: "14px 16px", borderRadius: 10, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <div>
          <p style={{ margin: 0, fontWeight: 700 }}>{fileName}</p>
          <p style={{ margin: "2px 0 0", fontSize: 12, color: "#24143099" }}>{fileSize}</p>
        </div>
        <button type="button" aria-label={`Download ${fileName}`}
          style={{ flex: "none", width: 32, height: 32, borderRadius: 999, border: "1.5px solid #24143030", background: state === "Complete" ? accent : "none", borderColor: state === "Complete" ? accent : "#24143030", cursor: "pointer", fontSize: 14 }}>&#8595;</button>
      </div>
      {state === "Downloading" && (
        <div style={{ height: 5, background: "#24143012", borderRadius: 999, marginTop: 10, overflow: "hidden" }}>
          <div role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100} aria-label={`Download progress for ${fileName}`}
            style={{ height: "100%", width: `${progress}%`, background: accent, borderRadius: 999 }} />
        </div>
      )}
    </div>
  );
}
